# U07 Orbit Loom: a small constellation game in the Reflection corner of the personal universe.
# Loaded by tool/l10n_source.py (fragments load in name order: after recovery.py, which defines universe_reflectionBody, and world.py).
# s(key, en, desc, te, te_Latn, ph=None, hi=, hl=) · edit(key, en=, te=, tl=, desc=, hi=, hl=)
# te / te_Latn / hi / hi_Latn (hl) are first drafts: NEED NATIVE REVIEW before alpha / beta.
# Voice: playful and unhurried. There is no right shape, score, timer or reward (RULES.md section 14).
# Meanings are neutral and equal: none is suggested; heavy and light ones sit side by side.

# ---- The game screen --------------------------------------------------------
s("loom_title", "Orbit Loom", "Title of the small constellation game. A proper name: keep it short; may stay in English.", "Orbit Loom", "Orbit Loom", hi="Orbit Loom", hl="Orbit Loom")
s("loom_intro", "Place a few stars and join them however you like. There's no right shape and no hurry.", "Intro line at the top of the game. Must say there is no right answer and no time limit.", "కొన్ని నక్షత్రాలు పెట్టి, మీకు నచ్చినట్టు కలపండి. సరైన ఆకారం అంటూ ఏదీ లేదు, తొందర కూడా లేదు.", "Konni nakshatraalu petti, meeku nachchinattu kalapandi. Saraina aakaaram antu edi ledu, tondara kooda ledu.", hi="कुछ तारे रखिए और जैसे मन हो, उन्हें जोड़िए। कोई सही आकार नहीं है, कोई जल्दी नहीं।", hl="Kuch taare rakhiye aur jaise mann ho, unhein jodiye. Koi sahi aakaar nahi hai, koi jaldi nahi.")
s("loom_modeTap", "Tap", "Mode switch: tap the sky to place stars and tap two stars to join them.", "టాప్", "Tap", hi="टैप", hl="Tap")
s("loom_modeDrag", "Drag", "Mode switch: drag between stars to join them and drag a star to move it.", "లాగండి", "Laagandi", hi="खींचें", hl="Kheenchein")
s("loom_hintTap", "Tap the sky to place a star. Tap two stars to join them, or tap them again to unjoin.", "Hint under the sky in tap mode.", "నక్షత్రం పెట్టడానికి ఆకాశాన్ని టాప్ చేయండి. రెండు నక్షత్రాలను కలపడానికి వాటిని టాప్ చేయండి; మళ్లీ టాప్ చేస్తే విడిపోతాయి.", "Nakshatram pettadaaniki aakaashaanni tap cheyandi. Rendu nakshatraalanu kalapadaaniki vaatini tap cheyandi; malli tap cheste vidipotaayi.", hi="तारा रखने के लिए आसमान पर टैप करें। दो तारों को जोड़ने के लिए उन्हें टैप करें; दोबारा टैप करने पर वे अलग हो जाते हैं।", hl="Taara rakhne ke liye aasmaan par tap karein. Do taaron ko jodne ke liye unhein tap karein; dobaara tap karne par ve alag ho jaate hain.")
s("loom_hintDrag", "Drag from one star to another to join them. Drag a star to move it.", "Hint under the sky in drag mode.", "రెండు నక్షత్రాలను కలపడానికి ఒకదాని నుండి మరొకదానికి లాగండి. కదపడానికి నక్షత్రాన్ని లాగండి.", "Rendu nakshatraalanu kalapadaaniki okadaani nundi marokadaaniki laagandi. Kadapadaaniki nakshatraanni laagandi.", hi="दो तारों को जोड़ने के लिए एक से दूसरे तक खींचें। किसी तारे को हिलाने के लिए उसे खींचें।", hl="Do taaron ko jodne ke liye ek se doosre tak kheenchein. Kisi taare ko hilaane ke liye use kheenchein.")
s("loom_addStar", "Add a star", "Button that places one star in a free spot, so no precise tapping is needed.", "ఒక నక్షత్రం చేర్చండి", "Oka nakshatram cherchandi", hi="एक तारा जोड़ें", hl="Ek taara jodein")
s("loom_scatter", "Scatter for me", "Button that places a few stars at once, spread out nicely.", "నా కోసం చల్లండి", "Naa kosam challandi", hi="मेरे लिए बिखेर दें", hl="Mere liye bikher dein")
s("loom_joinForMe", "Join for me", "Button that draws neat lines joining every star.", "నా కోసం కలపండి", "Naa kosam kalapandi", hi="मेरे लिए जोड़ दें", hl="Mere liye jod dein")
s("loom_undo", "Undo", "Undo the last change in the sky.", "రద్దు చేయండి", "Raddu cheyandi", hi="पहले जैसा करें", hl="Pehle jaisa karein")
s("loom_clear", "Start again", "Clears the sky to begin a new shape.", "మళ్లీ మొదలుపెట్టండి", "Malli modalupettandi", hi="फिर से शुरू करें", hl="Phir se shuru karein")
s("loom_full", "This sky holds seven stars. Join them, move them, or keep it.", "Shown when the seventh star is placed. Friendly, not a warning.", "ఈ ఆకాశంలో ఏడు నక్షత్రాలు పడతాయి. వాటిని కలపండి, కదపండి, లేదా దీన్ని ఉంచుకోండి.", "Ee aakaashamlo edu nakshatraalu padataayi. Vaatini kalapandi, kadapandi, leda deenni unchukondi.", hi="इस आसमान में सात तारे आते हैं। उन्हें जोड़िए, हिलाइए, या इसे रख लीजिए।", hl="Is aasmaan mein saat taare aate hain. Unhein jodiye, hilaaiye, ya ise rakh lijiye.")
s("loom_skyLabel", "Your sky: {stars, plural, =0{no stars yet} one{1 star} other{{stars} stars}}, {lines, plural, =0{no lines} one{1 line} other{{lines} lines}}", "Screen-reader summary of the sky canvas.", "మీ ఆకాశం: {stars, plural, =0{ఇంకా నక్షత్రాలు లేవు} one{1 నక్షత్రం} other{{stars} నక్షత్రాలు}}, {lines, plural, =0{గీతలు లేవు} one{1 గీత} other{{lines} గీతలు}}", "Mee aakaasham: {stars, plural, =0{inkaa nakshatraalu levu} one{1 nakshatram} other{{stars} nakshatraalu}}, {lines, plural, =0{geetalu levu} one{1 geeta} other{{lines} geetalu}}", INT("stars", "lines"), hi="आपका आसमान: {stars, plural, =0{अभी कोई तारा नहीं} one{1 तारा} other{{stars} तारे}}, {lines, plural, =0{कोई रेखा नहीं} one{1 रेखा} other{{lines} रेखाएँ}}", hl="Aapka aasmaan: {stars, plural, =0{abhi koi taara nahi} one{1 taara} other{{stars} taare}}, {lines, plural, =0{koi rekha nahi} one{1 rekha} other{{lines} rekhaayein}}")
s("loom_starLabel", "Star {index} of {count}, joined to {lines, plural, =0{no others} one{1 other} other{{lines} others}}", "Screen-reader label of one star. Activating it chooses it; activating a second star joins or unjoins the two.", "{count}లో {index}వ నక్షత్రం, {lines, plural, =0{దేనితోనూ కలవలేదు} one{1 దానితో కలిసింది} other{{lines} వాటితో కలిసింది}}", "{count} lo {index}va nakshatram, {lines, plural, =0{denitonu kalavaledu} one{1 daanito kalisindi} other{{lines} vaatito kalisindi}}", INT("index", "count", "lines"), hi="{count} में से तारा {index}, {lines, plural, =0{किसी से नहीं जुड़ा} one{1 से जुड़ा} other{{lines} से जुड़ा}}", hl="{count} mein se taara {index}, {lines, plural, =0{kisi se nahi juda} one{1 se juda} other{{lines} se juda}}")
s("loom_starChosen", "Chosen. Choose another star to join or unjoin them.", "Screen-reader hint after choosing a star in tap mode.", "ఎంచుకున్నారు. కలపడానికి లేదా విడదీయడానికి మరో నక్షత్రాన్ని ఎంచుకోండి.", "Enchukunnaaru. Kalapadaaniki leda vidadeeyadaaniki maro nakshatraanni enchukondi.", hi="चुन लिया। जोड़ने या अलग करने के लिए दूसरा तारा चुनें।", hl="Chun liya. Jodne ya alag karne ke liye doosra taara chunein.")
s("loom_meaningTitle", "A meaning, if you like", "Heading of the optional meaning chips. Choosing none is fine.", "మీకు నచ్చితే, ఒక అర్థం", "Meeku nachchite, oka artham", hi="मन हो तो, एक अर्थ", hl="Mann ho to, ek arth")
s("loom_meaning_noticed", "Something I noticed", "Optional neutral meaning of a constellation.", "నేను గమనించినది", "Nenu gamaninchinadi", hi="कुछ जो मैंने देखा", hl="Kuch jo maine dekha")
s("loom_meaning_carrying", "Something I'm carrying", "Optional neutral meaning of a constellation. Heavy things are as welcome as light ones.", "నేను మోస్తున్నది", "Nenu mostunnadi", hi="कुछ जो मेरे मन पर है", hl="Kuch jo mere mann par hai")
s("loom_meaning_ahead", "Something ahead", "Optional neutral meaning of a constellation.", "ముందున్నది", "Mundunnadi", hi="कुछ जो आगे है", hl="Kuch jo aage hai")
s("loom_meaning_thankful", "Something I'm thankful for", "Optional neutral meaning of a constellation.", "నేను కృతజ్ఞతగా ఉన్నది", "Nenu krutagnataga unnadi", hi="कुछ जिसके लिए मैं आभारी हूँ", hl="Kuch jiske liye main aabhaari hoon")
s("loom_meaning_just_because", "Just because", "Optional neutral meaning of a constellation: no reason needed.", "ఊరికే", "Oorike", hi="बस यूँ ही", hl="Bas yoon hi")
s("loom_keep", "Keep it in my sky", "Button that keeps the constellation in the Reflection sky. Nothing is awarded.", "నా ఆకాశంలో ఉంచండి", "Naa aakaashamlo unchandi", hi="मेरे आसमान में रखें", hl="Mere aasmaan mein rakhein")
s("loom_keepNeedsStars", "Place at least three stars to keep a shape.", "Shown under the disabled keep button until there are three stars.", "ఒక ఆకారాన్ని ఉంచడానికి కనీసం మూడు నక్షత్రాలు పెట్టండి.", "Oka aakaaraanni unchadaaniki kaneesam moodu nakshatraalu pettandi.", hi="आकार रखने के लिए कम से कम तीन तारे रखें।", hl="Aakaar rakhne ke liye kam se kam teen taare rakhein.")
s("loom_dayFull", "Your sky kept five today. You can keep playing; tomorrow there's room for more.", "Shown instead of the keep button after five kept today. Calm; playing is still welcome.", "ఈ రోజు మీ ఆకాశం ఐదు ఉంచింది. ఆడుతూనే ఉండొచ్చు; రేపు ఇంకా చోటు ఉంటుంది.", "Ee roju mee aakaasham aidu unchindi. Aadutoone undochu; repu inkaa chotu untundi.", hi="आज आपके आसमान ने पाँच रख लिए। आप खेलते रह सकते हैं; कल और जगह होगी।", hl="Aaj aapke aasmaan ne paanch rakh liye. Aap khelte reh sakte hain; kal aur jagah hogi.")
s("loom_kept", "Kept in your sky", "Brief confirmation after keeping a constellation.", "మీ ఆకాశంలో ఉంచాం", "Mee aakaashamlo unchaam", hi="आपके आसमान में रख दिया", hl="Aapke aasmaan mein rakh diya")
s("loom_close", "Leave Orbit Loom", "Tooltip of the close button. Leaving is always fine; nothing is lost that matters.", "Orbit Loom నుండి బయటకు", "Orbit Loom nundi bayataku", hi="Orbit Loom से बाहर", hl="Orbit Loom se baahar")

