s("universe_constellationsTitle", "Your constellations", "Heading of the kept constellations in the Reflection card.", "మీ నక్షత్ర మండలాలు", "Mee nakshatra mandalaalu", hi="आपके तारामंडल", hl="Aapke taaramandal")
s("universe_constellationLabel", "{meaning}, {stars, plural, one{1 star} other{{stars} stars}}", "Screen-reader and visible label of one kept constellation. {meaning} is a meaning or the word for 'A constellation'.", "{meaning}, {stars, plural, one{1 నక్షత్రం} other{{stars} నక్షత్రాలు}}", "{meaning}, {stars, plural, one{1 nakshatram} other{{stars} nakshatraalu}}", {"meaning": {"type": "String"}, "stars": {"type": "int"}}, hi="{meaning}, {stars, plural, one{1 तारा} other{{stars} तारे}}", hl="{meaning}, {stars, plural, one{1 taara} other{{stars} taare}}")
s("universe_constellationPlain", "A constellation", "Label of a kept constellation that has no meaning chosen.", "ఒక నక్షత్ర మండలం", "Oka nakshatra mandalam", hi="एक तारामंडल", hl="Ek taaramandal")
s("universe_letGo", "Let it go", "Action that removes one kept constellation from every device.", "వదిలేయండి", "Vadileyandi", hi="जाने दें", hl="Jaane dein")
s("universe_letGoTitle", "Let this constellation go?", "Confirm dialog title before removing a kept constellation.", "ఈ నక్షత్ర మండలాన్ని వదిలేయాలా?", "Ee nakshatra mandalaanni vadileyaalaa?", hi="इस तारामंडल को जाने दें?", hl="Is taaramandal ko jaane dein?")
s("universe_letGoBody", "It leaves your sky on every device where you're signed in.", "Confirm dialog body before removing a kept constellation.", "మీరు సైన్ ఇన్ అయిన ప్రతి పరికరంలో ఇది మీ ఆకాశం నుండి వెళ్లిపోతుంది.", "Meeru sign in ayina prati parikaramlo idi mee aakaasham nundi vellipotundi.", hi="यह उन सभी डिवाइस पर आपके आसमान से चला जाएगा जहाँ आप साइन इन हैं।", hl="Yeh un sabhi device par aapke aasmaan se chala jaayega jahaan aap sign in hain.")
s("universe_letGoKeep", "Keep it", "Confirm dialog button that cancels removing a constellation.", "ఉంచండి", "Unchandi", hi="रहने दें", hl="Rehne dein")

